/**
 * Static artwork embedded in every generated pay slip: the Apollo Ventures
 * header banner, the accountant stamp and the accountant signature.
 *
 * Stored as base64 so the PDF generator never touches the filesystem at
 * runtime (serverless bundles do not reliably include files under public/).
 * Extracted from the reference pay slip supplied by Finance (Sept 2026).
 */

export const PAYSLIP_BANNER_JPEG_BASE64 =
  ''

export const PAYSLIP_STAMP_PNG_BASE64 =
  ''

export const PAYSLIP_SIGNATURE_PNG_BASE64 =
  ''

// Decoded once per process; the send route generates one PDF per employee.
let bannerCache: Buffer | null = null
let stampCache: Buffer | null = null
let signatureCache: Buffer | null = null

export function payslipBannerBuffer(): Buffer {
  bannerCache ??= Buffer.from(PAYSLIP_BANNER_JPEG_BASE64, 'base64')
  return bannerCache
}

export function payslipStampBuffer(): Buffer {
  stampCache ??= Buffer.from(PAYSLIP_STAMP_PNG_BASE64, 'base64')
  return stampCache
}

export function payslipSignatureBuffer(): Buffer {
  signatureCache ??= Buffer.from(PAYSLIP_SIGNATURE_PNG_BASE64, 'base64')
  return signatureCache
}
